template.schema:
interface Input {
  service: string;
  reportedIssue: string;
}

interface Output {
  service: string;
  severity: "low" | "medium" | "high" | "critical";
  rootCauseSummary: string;
  metricsAnalysis: string;
  actionPlan: {
    priority: number;
    action: string;
    suggestedCommand?: string;
  }[];
  followUpRecommendation: string;
}
